package com.campus.registration;
import com.campus.registration.model.*;import com.campus.registration.repository.*;import com.campus.registration.service.*;import com.campus.registration.report.*;import com.campus.registration.util.SeedData;import java.nio.file.*;import java.util.*;
public class Main{public static void main(String[]a)throws Exception{Files.createDirectories(Path.of("data"));Database db=new Database("data/campus.db");db.init();StudentRepository sr=new StudentRepository(db);CourseRepository cr=new CourseRepository(db);RegistrationRepository rr=new RegistrationRepository(db);PrerequisiteGraph g=new PrerequisiteGraph();if(cr.all().isEmpty())SeedData.load(sr,cr,g);else for(Course c:cr.all())g.add(c);RegistrationEngine e=new RegistrationEngine(cr,rr,g);ReportService rep=new ReportService(cr,rr);Scanner in=new Scanner(System.in);System.out.println("\nCAMPUS COURSE REGISTRATION & TIMETABLE CONFLICT RESOLVER");System.out.println("Student: S1001 | Yojit Wagh");while(true){System.out.println("\n1.List courses 2.Register 3.My timetable 4.Seat report 5.Clash logs 6.Prerequisite order 0.Exit");System.out.print("Choice: ");String x=in.nextLine().trim();try{switch(x){case"1"->cr.all().forEach(c->System.out.println(c.code()+" - "+c.name()+" | seats "+c.capacity()+" | prereq "+c.prerequisites()));case"2"->{System.out.print("Course code: ");String c=in.nextLine().trim().toUpperCase();System.out.print("Section: ");String s=in.nextLine().trim().toUpperCase();e.register("S1001",c,s);System.out.println("Registration successful.");}case"3"->rep.printTimetable("S1001");case"4"->rep.printSeatUtilization();case"5"->rep.printClashLogs();case"6"->System.out.println(g.topologicalOrder());case"0"->{return;}default->System.out.println("Invalid choice.");}}catch(Exception z){System.out.println("Registration rejected: "+z.getMessage());}}}}
